html:
{% set company = frappe.get_doc("Company", doc.company) %}
{# Distinct Sales Orders this DN was made against — Delivery Note Item's real
   field is `against_sales_order` (verified via doctype meta), not "sales_order". #}
{% set ns_so = namespace(v=[]) %}
{% for row in doc.items %}
  {% if row.against_sales_order and row.against_sales_order not in ns_so.v %}
    {% set _ = ns_so.v.append(row.against_sales_order) %}
  {% endif %}
{% endfor %}
{% macro fd(d) %}{% if d %}{{ frappe.utils.formatdate(d, "dd-MMM-yy") }}{% endif %}{% endmacro %}
{% macro fq(v) %}{{ frappe.utils.fmt_money(v|float, precision=2) }}{% endmacro %}

{# Same visual system as IB Purchase Order — circular logo, centered title,
   black-bordered tables, single font — brought over here to match. #}
<style>
  body, table, th, td { font-family: Arial, sans-serif; }
  body   { font-size: 11px; color: #000; margin: 0; }
  table  { width: 100%; border-collapse: collapse; }
  td, th { padding: 4px 6px; vertical-align: top; }
  {# table-layout:fixed forces columns to obey their declared width % —
     without it, a long unbreakable string (item code) makes the
     browser/PDF engine widen that column past its % and the whole table
     overflows the page. Blanket break-word on every cell was tried first
     and made short header words fragment mid-word — .wrap-anywhere
     targets only the cell that actually carries a long unbreakable token
     (item code). #}
  .items-tbl { table-layout: fixed; }
  .items-tbl td, .items-tbl th { text-align: center; padding: 3px 4px; word-break: normal; }
  .items-tbl .wrap-anywhere { overflow-wrap: anywhere; }
  strong { font-weight: bold; }
  .box   { border: 1.5px solid #000; margin-bottom: 2px; }
  .b     { border: 1px solid #000; }
  .bb    { border-bottom: 1px solid #000; }
  .bt    { border-top: 1px solid #000; }
  .br    { border-right: 1px solid #000; }
  .ta-r  { text-align: right; }
  .ta-c  { text-align: center; }
  .lbl   { color: #555; font-size: 10px; }
  .italic{ font-style: italic; }
  .watermark { position: fixed; top: 0; left: 0; width: 100vw; height: 100vh;
               display: flex; align-items: center; justify-content: center;
               pointer-events: none; z-index: 99999; overflow: hidden; }
  .watermark span { display: block; font-size: 110px; font-weight: 900;
                    color: rgba(211,47,47,.15); letter-spacing: 10px;
                    text-transform: uppercase; white-space: nowrap;
                    transform: rotate(-40deg); font-family: Arial, sans-serif;
                    border: 12px solid rgba(211,47,47,.12);
                    padding: 10px 30px; border-radius: 8px; }
</style>

{% if doc.docstatus == 2 %}
<div class="watermark"><span>CANCELLED</span></div>
{% endif %}

<div class="box">

  {# ── Header: circular logo (left) + centered title + Location/Date (right) — mirrors IB Purchase Order #}
  <div style="position:relative">
    <table class="bb">
      <tr>
        <td style="width:18%; padding:6px">
          <img src="/files/logo.jpeg" style="display:block; width:100%; height:auto; object-fit:contain">
        </td>
        <td style="width:52%">&nbsp;</td>
        <td style="width:30%; text-align:right; vertical-align:middle; font-size:11px">
          {% if doc.custom_location %}Location: <strong>{{ doc.custom_location }}</strong><br>{% endif %}
          Date: <strong>{{ fd(doc.posting_date) }}</strong>
        </td>
      </tr>
    </table>
    <div style="position:absolute; top:0; left:0; width:100%; height:100%; display:table">
      <div style="display:table-cell; vertical-align:middle; text-align:center">
        <div style="font-size:20px; font-weight:bold; letter-spacing:1px">DELIVERY NOTE</div>
      </div>
    </div>
  </div>

  {# ── Company header (left) + DN meta grid (right) ── #}
  <table class="bb">
    <tr>
      <td class="br" style="width:55%">
        <strong>{{ doc.company | upper }}</strong><br>
        {% if doc.company_address_display %}
          {{ doc.company_address_display | safe }}
        {% endif %}
      </td>
      <td style="width:45%; padding:0; vertical-align:top">
        <table>
          <tr>
            <td class="bb br lbl" style="width:50%">DN Number</td>
            <td class="bb lbl">Customer</td>
          </tr>
          <tr>
            <td class="bb br"><strong>{{ doc.name }}</strong></td>
            <td class="bb"><strong>{{ doc.customer_name or doc.customer }}</strong></td>
          </tr>
          {% if ns_so.v %}
          <tr>
            <td colspan="2" class="bb lbl">Other References</td>
          </tr>
          <tr>
            <td colspan="2" class="bb"><strong>{{ ns_so.v | join(", ") }}</strong></td>
          </tr>
          {% endif %}
          {% if doc.transporter_name or doc.custom_transport or doc.vehicle_no %}
          <tr>
            <td class="bb br lbl">Transporter</td>
            <td class="bb lbl">Vehicle No.</td>
          </tr>
          <tr>
            <td class="bb br">{{ doc.transporter_name or doc.custom_transport or "—" }}</td>
            <td class="bb">{{ doc.vehicle_no or "—" }}</td>
          </tr>
          {% endif %}
          {% if doc.custom_lr_number or doc.lr_no %}
          <tr>
            <td class="bb br lbl">LR No.</td>
            <td class="bb lbl">LR Date</td>
          </tr>
          <tr>
            <td class="bb br">{{ doc.custom_lr_number or doc.lr_no }}</td>
            <td class="bb">{{ fd(doc.lr_date) if doc.lr_date else "—" }}</td>
          </tr>
          {% endif %}
        </table>
      </td>
    </tr>
  </table>

  {# ── Ship To / Dispatch From ── #}
  <table class="bb">
    <tr>
      <td class="br" style="width:55%">
        <div class="lbl">Ship To</div>
        {{ doc.shipping_address or doc.address_display or "" }}
      </td>
      <td style="width:45%">
        {% if doc.dispatch_address %}
        <div class="lbl">Dispatch From</div>
        {{ doc.dispatch_address }}
        {% endif %}
      </td>
    </tr>
  </table>

  {# ── Items table ── #}
  <table class="items-tbl">
    <thead>
      <tr>
        <th class="b" style="width:3%">Sl<br>No.</th>
        <th class="b" style="width:14%">Item Code</th>
        <th class="b" style="width:24%">Description</th>
        <th class="b" style="width:9%">Branding</th>
        <th class="b" style="width:8%">Qty</th>
        <th class="b" style="width:6%">UOM</th>
        <th class="b" style="width:8%">Rolls/<br>Box</th>
        <th class="b" style="width:9%">No. of<br>Boxes</th>
        <th class="b" style="width:9%">Carton<br>Wt (kg)</th>
        <th class="b" style="width:9%">Total<br>Wt (kg)</th>
        <th class="b" style="width:11%">Marking</th>
      </tr>
    </thead>
    <tbody>
      {% set total_boxes = namespace(v=0) %}
      {% set total_wt = namespace(v=0.0) %}
      {% for row in doc.items %}
        {% set item = frappe.get_cached_doc("Item", row.item_code) %}
        {% set rolls_per_box = item.custom_rolls_per_box or 1 %}
        {% set carton_wt = item.custom_carton_weight_kg or 0 %}
        {% set boxes = (row.qty / rolls_per_box) | round(2) %}
        {% set line_wt = (boxes * carton_wt) | round(2) %}
        {% set total_boxes.v = total_boxes.v + boxes %}
        {% set total_wt.v = total_wt.v + line_wt %}
        <tr>
          <td class="b">{{ loop.index }}</td>
          <td class="b wrap-anywhere">{{ row.item_code }}</td>
          <td class="b wrap-anywhere">
            <strong>{{ row.item_name or row.item_code }}</strong>
            {% if row.description and row.description != row.item_name %}
            <br><span class="italic lbl">{{ row.description | striptags | trim }}</span>
            {% endif %}
          </td>
          <td class="b">{{ row.custom_branding or "" }}</td>
          <td class="b">{{ fq(row.qty) }}</td>
          <td class="b">{{ row.uom }}</td>
          <td class="b">{{ rolls_per_box }}</td>
          <td class="b">{{ boxes }}</td>
          <td class="b">{{ carton_wt }}</td>
          <td class="b">{{ line_wt }}</td>
          <td class="b">{{ row.custom_marking or item.custom_carton_marking or "" }}</td>
        </tr>
      {% endfor %}
      <tr>
        <td class="b" colspan="7"><strong>TOTAL</strong></td>
        <td class="b"><strong>{{ total_boxes.v | round(2) }}</strong></td>
        <td class="b"></td>
        <td class="b"><strong>{{ total_wt.v | round(2) }}</strong></td>
        <td class="b"></td>
      </tr>
    </tbody>
  </table>

  {# ── Signature ── #}
  <table class="bt">
    <tr>
      <td style="width:33%; text-align:center; padding:30px 6px 4px">
        <strong>Packed By</strong>
      </td>
      <td style="width:33%; text-align:center; padding:30px 6px 4px; border-left:1px solid #000">
        <strong>Checked By</strong>
      </td>
      <td style="text-align:right; padding:6px; border-left:1px solid #000">
        <div><strong>for {{ doc.company | upper }}</strong></div>
        <div style="text-align:right; margin-top:4px">
          <img src="/files/IB_Stamp.jpeg" style="height:55px; width:auto; display:inline-block">
        </div>
        <div style="margin-top:6px"><strong>Authorised Signatory</strong></div>
      </td>
    </tr>
  </table>

  <div style="text-align:center; padding:3px; border-top:1px solid #000">
    This is a Computer Generated Delivery Note
  </div>

</div>
